// Super Mario World — native PC port, SDL2 frontend.
//
// Window/renderer, keyboard + game controller input, audio output, frame
// pacing, battery save (SRAM), save states and a small INI config.
#define SDL_MAIN_HANDLED
#include <SDL.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "snes.h"
#include "ppu.h"
#include "apu.h"
#include "smw_build_config.h"   // generated by CMake: SMW_BUILD_ROM_PATH
#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#endif

#define FRAME_RATE 60.0988138974405   // NTSC SNES
#define APP_TITLE "Super Mario World"

// ------------------------------------------------------------------ config
typedef struct Config {
  int window_scale;
  int fullscreen;
  int aspect_4_3;        // 1: stretch to 4:3 like a CRT, 0: square pixels (8:7)
  int linear_filter;
  int audio_enabled;
  int volume;            // 0..100
  int audio_latency_frames;
  SDL_Keycode keys[12];  // order: see key_names
  char rom_path[1024];
} Config;

static const char *const key_names[12] = {"Up", "Down", "Left", "Right", "A", "B", "X", "Y", "L", "R", "Start", "Select"};
static const uint16_t key_bits[12] = {JOY_UP, JOY_DOWN, JOY_LEFT, JOY_RIGHT, JOY_A, JOY_B, JOY_X, JOY_Y, JOY_L, JOY_R, JOY_START, JOY_SELECT};
static const char *const key_defaults[12] = {"Up", "Down", "Left", "Right", "X", "Z", "S", "A", "Q", "W", "Return", "Right Shift"};

static Config cfg;
static char base_dir[1024];

static void path_join(char *out, size_t n, const char *dir, const char *file) {
  snprintf(out, n, "%s%s", dir, file);
}

static void config_defaults(void) {
  cfg.window_scale = 3;
  cfg.fullscreen = 0;
  cfg.aspect_4_3 = 0;
  cfg.linear_filter = 0;
  cfg.audio_enabled = 1;
  cfg.volume = 100;
  cfg.audio_latency_frames = 4;
  for (int i = 0; i < 12; i++) cfg.keys[i] = SDL_GetKeyFromName(key_defaults[i]);
  cfg.rom_path[0] = 0;
}

static void write_default_config(const char *path) {
  FILE *f = fopen(path, "w");
  if (!f) return;
  fprintf(f,
          "; Super Mario World native port configuration\n"
          "[General]\n"
          "; Path to your Super Mario World (USA) ROM (.sfc/.smc). Empty = the ROM the game was built\n"
          "; from, or smw.sfc / smw.smc next to the exe\n"
          "Rom=\n\n"
          "[Video]\n"
          "WindowScale=3\n"
          "Fullscreen=0\n"
          "; 1 = 4:3 display aspect like a TV, 0 = square pixels\n"
          "Aspect4x3=0\n"
          "LinearFilter=0\n\n"
          "[Audio]\n"
          "Enable=1\n"
          "Volume=100\n"
          "LatencyFrames=4\n\n"
          "[Keyboard]\n"
          "; SDL key names, e.g. Z, X, A, S, Return, Right Shift, Space, Left Ctrl\n");
  for (int i = 0; i < 12; i++) fprintf(f, "%s=%s\n", key_names[i], key_defaults[i]);
  fprintf(f, "\n; Game controllers (XInput/DualShock/etc.) are mapped automatically:\n"
             "; South=B  East=A  West=Y  North=X  LB/LT=L  RB/RT=R  Start=Start  Back=Select  D-pad/left stick=move\n");
  fclose(f);
}

static char *trim(char *s) {
  while (*s && isspace((unsigned char)*s)) s++;
  char *e = s + strlen(s);
  while (e > s && isspace((unsigned char)e[-1])) *--e = 0;
  return s;
}

static void load_config(void) {
  char path[1100];
  path_join(path, sizeof path, base_dir, "smw.ini");
  config_defaults();
  FILE *f = fopen(path, "r");
  if (!f) { write_default_config(path); return; }
  char line[1200], section[64] = "";
  while (fgets(line, sizeof line, f)) {
    char *s = trim(line);
    if (!*s || *s == ';' || *s == '#') continue;
    if (*s == '[') { char *e = strchr(s, ']'); if (e) *e = 0; snprintf(section, sizeof section, "%s", s + 1); continue; }
    char *eq = strchr(s, '=');
    if (!eq) continue;
    *eq = 0;
    char *k = trim(s), *v = trim(eq + 1);
    if (!SDL_strcasecmp(section, "General") && !SDL_strcasecmp(k, "Rom")) snprintf(cfg.rom_path, sizeof cfg.rom_path, "%s", v);
    else if (!SDL_strcasecmp(k, "WindowScale")) cfg.window_scale = SDL_max(1, SDL_min(8, atoi(v)));
    else if (!SDL_strcasecmp(k, "Fullscreen")) cfg.fullscreen = atoi(v);
    else if (!SDL_strcasecmp(k, "Aspect4x3")) cfg.aspect_4_3 = atoi(v);
    else if (!SDL_strcasecmp(k, "LinearFilter")) cfg.linear_filter = atoi(v);
    else if (!SDL_strcasecmp(section, "Audio") && !SDL_strcasecmp(k, "Enable")) cfg.audio_enabled = atoi(v);
    else if (!SDL_strcasecmp(k, "Volume")) cfg.volume = SDL_max(0, SDL_min(100, atoi(v)));
    else if (!SDL_strcasecmp(k, "LatencyFrames")) cfg.audio_latency_frames = SDL_max(2, SDL_min(12, atoi(v)));
    else if (!SDL_strcasecmp(section, "Keyboard")) {
      for (int i = 0; i < 12; i++)
        if (!SDL_strcasecmp(k, key_names[i])) {
          SDL_Keycode kc = SDL_GetKeyFromName(v);
          if (kc != SDLK_UNKNOWN) cfg.keys[i] = kc;
          else fprintf(stderr, "smw.ini: unknown key name '%s' for %s\n", v, k);
        }
    }
  }
  fclose(f);
}

// ------------------------------------------------------------------ ROM
static uint8_t *read_file(const char *path, size_t *size) {
  FILE *f = fopen(path, "rb");
  if (!f) return NULL;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (n <= 0 || n > 16 * 1024 * 1024) { fclose(f); return NULL; }
  uint8_t *d = (uint8_t *)malloc((size_t)n);
  if (d && fread(d, 1, (size_t)n, f) != (size_t)n) { free(d); d = NULL; }
  fclose(f);
  if (d) *size = (size_t)n;
  return d;
}

static bool try_rom(const char *path) {
  size_t n;
  uint8_t *d = read_file(path, &n);
  if (!d) return false;
  bool ok = snes_load_rom(d, n);
  free(d);
  if (ok) fprintf(stderr, "Loaded ROM: %s\n", path);
  return ok;
}

static bool find_and_load_rom(int argc, char **argv) {
  char p[1200];
  for (int i = 1; i < argc; i++) {
    if (!strcmp(argv[i], "--autotest")) { i++; continue; }
    if (argv[i][0] != '-') return try_rom(argv[i]);
  }
  if (cfg.rom_path[0] && try_rom(cfg.rom_path)) return true;
  if (try_rom(SMW_BUILD_ROM_PATH)) return true;
  static const char *const names[] = { "smw.sfc", "smw.smc", "../smw.sfc", "../smw.smc" };
  for (size_t i = 0; i < sizeof names / sizeof names[0]; i++) {
    path_join(p, sizeof p, base_dir, names[i]);
    if (try_rom(p)) return true;
    if (try_rom(names[i])) return true;
  }
  return false;
}

// ------------------------------------------------------------------ persistence
static char sram_path[1100], state_path[1100];

static void load_sram(void) {
  size_t n;
  uint8_t *d = read_file(sram_path, &n);
  if (d) {
    if (n == snes_sram_size()) memcpy(snes_sram(), d, n);
    free(d);
  }
}

static void save_sram(void) {
  FILE *f = fopen(sram_path, "wb");
  if (!f) return;
  fwrite(snes_sram(), 1, snes_sram_size(), f);
  fclose(f);
}

static bool save_state(void) {
  size_t n = snes_save_state(NULL);
  uint8_t *b = (uint8_t *)malloc(n);
  if (!b) return false;
  snes_save_state(b);
  FILE *f = fopen(state_path, "wb");
  bool ok = f && fwrite(b, 1, n, f) == n;
  if (f) fclose(f);
  free(b);
  return ok;
}

static bool load_state(void) {
  size_t n;
  uint8_t *b = read_file(state_path, &n);
  if (!b) return false;
  bool ok = snes_load_state(b, n);
  free(b);
  return ok;
}

// ------------------------------------------------------------------ input
static SDL_GameController *pads[4];
static uint16_t kb_state;

static void open_pad(int index) {
  if (!SDL_IsGameController(index)) return;
  for (int i = 0; i < 4; i++) {
    if (!pads[i]) {
      pads[i] = SDL_GameControllerOpen(index);
      if (pads[i]) fprintf(stderr, "Controller %d: %s\n", i + 1, SDL_GameControllerName(pads[i]));
      return;
    }
  }
}

static void close_pad(SDL_JoystickID id) {
  for (int i = 0; i < 4; i++) {
    if (pads[i] && SDL_JoystickInstanceID(SDL_GameControllerGetJoystick(pads[i])) == id) {
      SDL_GameControllerClose(pads[i]);
      pads[i] = NULL;
    }
  }
}

static uint16_t pad_buttons(SDL_GameController *c) {
  uint16_t b = 0;
  if (!c) return 0;
  struct { SDL_GameControllerButton btn; uint16_t bit; } map[] = {
    {SDL_CONTROLLER_BUTTON_A, JOY_B}, {SDL_CONTROLLER_BUTTON_B, JOY_A},
    {SDL_CONTROLLER_BUTTON_X, JOY_Y}, {SDL_CONTROLLER_BUTTON_Y, JOY_X},
    {SDL_CONTROLLER_BUTTON_LEFTSHOULDER, JOY_L}, {SDL_CONTROLLER_BUTTON_RIGHTSHOULDER, JOY_R},
    {SDL_CONTROLLER_BUTTON_START, JOY_START}, {SDL_CONTROLLER_BUTTON_BACK, JOY_SELECT},
    {SDL_CONTROLLER_BUTTON_DPAD_UP, JOY_UP}, {SDL_CONTROLLER_BUTTON_DPAD_DOWN, JOY_DOWN},
    {SDL_CONTROLLER_BUTTON_DPAD_LEFT, JOY_LEFT}, {SDL_CONTROLLER_BUTTON_DPAD_RIGHT, JOY_RIGHT},
  };
  for (size_t i = 0; i < sizeof map / sizeof map[0]; i++)
    if (SDL_GameControllerGetButton(c, map[i].btn)) b |= map[i].bit;
  const int dead = 16000;
  int ax = SDL_GameControllerGetAxis(c, SDL_CONTROLLER_AXIS_LEFTX);
  int ay = SDL_GameControllerGetAxis(c, SDL_CONTROLLER_AXIS_LEFTY);
  if (ax < -dead) b |= JOY_LEFT;
  if (ax > dead) b |= JOY_RIGHT;
  if (ay < -dead) b |= JOY_UP;
  if (ay > dead) b |= JOY_DOWN;
  if (SDL_GameControllerGetAxis(c, SDL_CONTROLLER_AXIS_TRIGGERLEFT) > 16000) b |= JOY_L;
  if (SDL_GameControllerGetAxis(c, SDL_CONTROLLER_AXIS_TRIGGERRIGHT) > 16000) b |= JOY_R;
  return b;
}

static uint16_t sanitize(uint16_t b) {
  // a real D-pad cannot press opposite directions at once; SMW glitches if it sees that
  if ((b & (JOY_LEFT | JOY_RIGHT)) == (JOY_LEFT | JOY_RIGHT)) b &= ~(JOY_LEFT | JOY_RIGHT);
  if ((b & (JOY_UP | JOY_DOWN)) == (JOY_UP | JOY_DOWN)) b &= ~(JOY_UP | JOY_DOWN);
  return b;
}

// ------------------------------------------------------------------ video
static SDL_Window *window;
static SDL_Renderer *renderer;
static SDL_Texture *texture;

static void present(void) {
  SDL_UpdateTexture(texture, NULL, ppu_framebuffer(), PPU_WIDTH * 4);
  int ww, wh;
  SDL_GetRendererOutputSize(renderer, &ww, &wh);
  double aspect = cfg.aspect_4_3 ? 4.0 / 3.0 : (double)PPU_WIDTH / PPU_HEIGHT;
  int w = ww, h = (int)(ww / aspect + 0.5);
  if (h > wh) { h = wh; w = (int)(wh * aspect + 0.5); }
  SDL_Rect dst = {(ww - w) / 2, (wh - h) / 2, w, h};
  SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
  SDL_RenderClear(renderer);
  SDL_RenderCopy(renderer, texture, NULL, &dst);
  SDL_RenderPresent(renderer);
}

static void screenshot(void) {
  SDL_Surface *s = SDL_CreateRGBSurfaceFrom(ppu_framebuffer(), PPU_WIDTH, PPU_HEIGHT, 32, PPU_WIDTH * 4,
                                            0x00FF0000, 0x0000FF00, 0x000000FF, 0);
  if (!s) return;
  char p[1200];
  for (int i = 0; i < 1000; i++) {
    snprintf(p, sizeof p, "%sscreenshot_%03d.bmp", base_dir, i);
    FILE *f = fopen(p, "rb");
    if (f) { fclose(f); continue; }
    SDL_SaveBMP(s, p);
    fprintf(stderr, "Saved %s\n", p);
    break;
  }
  SDL_FreeSurface(s);
}

// ------------------------------------------------------------------ main
int main(int argc, char **argv) {
#ifdef _WIN32
  // GUI-subsystem build: still print diagnostics when started from a terminal
  if (AttachConsole(ATTACH_PARENT_PROCESS)) {
    freopen("CONOUT$", "w", stderr);
    freopen("CONOUT$", "w", stdout);
  }
#endif
  SDL_SetMainReady();
  char *bp = SDL_GetBasePath();
  snprintf(base_dir, sizeof base_dir, "%s", bp ? bp : "");
  SDL_free(bp);
  load_config();

  if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO | SDL_INIT_GAMECONTROLLER | SDL_INIT_EVENTS) != 0) {
    fprintf(stderr, "SDL_Init failed: %s\n", SDL_GetError());
    return 1;
  }
  char dbp[1200];
  path_join(dbp, sizeof dbp, base_dir, "gamecontrollerdb.txt");
  SDL_GameControllerAddMappingsFromFile(dbp);

  if (!find_and_load_rom(argc, argv)) {
    char msg[600];
    snprintf(msg, sizeof msg,
             "Could not load the Super Mario World ROM.\n\n"
             "Place your Super Mario World (USA) ROM next to smw.exe as smw.sfc\n"
             "(or set Rom= in smw.ini), or pass its path on the command line.\n\n"
             "Expected SHA-1 (headerless): %s",
             snes_rom_sha1_expected());
    SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, APP_TITLE, msg, NULL);
    fprintf(stderr, "%s\n", msg);
    return 1;
  }
  path_join(sram_path, sizeof sram_path, base_dir, "smw.srm");
  path_join(state_path, sizeof state_path, base_dir, "smw.state");

  bool force_interp = false;
  int autotest_frames = 0;   // --autotest N: run N frames, save a screenshot, exit (smoke test)
  for (int i = 1; i < argc; i++) {
    if (!strcmp(argv[i], "--interpreter")) force_interp = true;
    if (!strcmp(argv[i], "--autotest") && i + 1 < argc) autotest_frames = atoi(argv[++i]);
  }
  snes_set_force_interpreter(force_interp);

  ppu_init();
  apu_init();
  snes_reset();
  load_sram();

  window = SDL_CreateWindow(APP_TITLE, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                            (cfg.aspect_4_3 ? 299 : PPU_WIDTH) * cfg.window_scale, PPU_HEIGHT * cfg.window_scale,
                            SDL_WINDOW_RESIZABLE | SDL_WINDOW_ALLOW_HIGHDPI |
                            (cfg.fullscreen ? SDL_WINDOW_FULLSCREEN_DESKTOP : 0));
  if (!window) { fprintf(stderr, "SDL_CreateWindow: %s\n", SDL_GetError()); return 1; }
  SDL_SetHint(SDL_HINT_RENDER_SCALE_QUALITY, cfg.linear_filter ? "linear" : "nearest");
  renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
  if (!renderer) renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_SOFTWARE);
  texture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING, PPU_WIDTH, PPU_HEIGHT);

  SDL_AudioDeviceID audio = 0;
  if (cfg.audio_enabled) {
    SDL_AudioSpec want = {0}, have;
    want.freq = APU_SAMPLE_RATE;
    want.format = AUDIO_S16SYS;
    want.channels = 2;
    want.samples = 512;
    audio = SDL_OpenAudioDevice(NULL, 0, &want, &have, 0);
    if (audio) SDL_PauseAudioDevice(audio, 0);
    else fprintf(stderr, "Audio disabled: %s\n", SDL_GetError());
  }

  for (int i = 0; i < SDL_NumJoysticks(); i++) open_pad(i);

  const uint64_t freq = SDL_GetPerformanceFrequency();
  const double frame_ticks = (double)freq / FRAME_RATE;
  double next_frame = (double)SDL_GetPerformanceCounter();
  bool running = true, paused = false, fast = false;
  int16_t abuf[4096 * 2];
  int frame = 0;
  const int samples_per_frame = (int)(APU_SAMPLE_RATE / FRAME_RATE + 1);

  while (running) {
    SDL_Event ev;
    while (SDL_PollEvent(&ev)) {
      switch (ev.type) {
      case SDL_QUIT: running = false; break;
      case SDL_CONTROLLERDEVICEADDED: open_pad(ev.cdevice.which); break;
      case SDL_CONTROLLERDEVICEREMOVED: close_pad(ev.cdevice.which); break;
      case SDL_KEYDOWN:
      case SDL_KEYUP: {
        bool down = ev.type == SDL_KEYDOWN;
        SDL_Keycode k = ev.key.keysym.sym;
        for (int i = 0; i < 12; i++)
          if (k == cfg.keys[i]) kb_state = down ? (kb_state | key_bits[i]) : (kb_state & ~key_bits[i]);
        if (k == SDLK_TAB) fast = down;
        if (!down || ev.key.repeat) break;
        if (k == SDLK_ESCAPE) running = false;
        else if (k == SDLK_F11 || (k == SDLK_RETURN && (ev.key.keysym.mod & KMOD_ALT))) {
          cfg.fullscreen = !cfg.fullscreen;
          SDL_SetWindowFullscreen(window, cfg.fullscreen ? SDL_WINDOW_FULLSCREEN_DESKTOP : 0);
        } else if (k == SDLK_p || k == SDLK_PAUSE) paused = !paused;
        else if (k == SDLK_F5) fprintf(stderr, save_state() ? "State saved\n" : "State save failed\n");
        else if (k == SDLK_F9) fprintf(stderr, load_state() ? "State loaded\n" : "No state to load\n");
        else if (k == SDLK_F12) screenshot();
        else if (k == SDLK_F1) { snes_reset(); load_sram(); }
        break;
      }
      }
    }
    if (paused) { SDL_Delay(16); present(); next_frame = (double)SDL_GetPerformanceCounter(); continue; }

    if (autotest_frames) {
      // inject real key events (Start, then B) to exercise the keyboard path end to end
      static const struct { int frame, key, down; } seq[] = {
        {400, 10, 1}, {405, 10, 0}, {500, 5, 1}, {505, 5, 0},
      };
      for (size_t i = 0; i < sizeof seq / sizeof seq[0]; i++)
        if (seq[i].frame == frame) {
          SDL_Event k = {0};
          k.type = seq[i].down ? SDL_KEYDOWN : SDL_KEYUP;
          k.key.keysym.sym = cfg.keys[seq[i].key];
          SDL_PushEvent(&k);
        }
    }
    uint16_t joy1 = kb_state | pad_buttons(pads[0]);
    snes_set_joypad(0, sanitize(joy1));
    snes_set_joypad(1, sanitize(pad_buttons(pads[1])));

    snes_run_frame();
    frame++;

    // audio: queue what the APU produced, keeping latency bounded
    int n = apu_read_samples(abuf, 4096);
    if (audio && !fast) {
      uint32_t queued = SDL_GetQueuedAudioSize(audio) / 4;
      uint32_t max_q = (uint32_t)(samples_per_frame * cfg.audio_latency_frames);
      if (queued > max_q) n = 0;                       // drop to catch up
      if (cfg.volume < 100)
        for (int i = 0; i < n * 2; i++) abuf[i] = (int16_t)(abuf[i] * cfg.volume / 100);
      if (n > 0) SDL_QueueAudio(audio, abuf, (uint32_t)n * 4);
    }

    if (snes_sram_take_dirty()) save_sram();
    if (autotest_frames && frame >= autotest_frames) {
      present();
      screenshot();
      fprintf(stderr, "autotest: %d frames, audio %s, renderer ok\n", frame, audio ? "on" : "off");
      running = false;
    }

    if (fast && (frame % 4) != 0) continue;
    present();

    // pacing
    next_frame += frame_ticks;
    double now = (double)SDL_GetPerformanceCounter();
    if (fast) { next_frame = now; continue; }
    if (now > next_frame + frame_ticks * 4) next_frame = now;   // fell behind: resync
    while ((now = (double)SDL_GetPerformanceCounter()) < next_frame) {
      double ms = (next_frame - now) * 1000.0 / (double)freq;
      if (ms > 2.0) SDL_Delay((Uint32)(ms - 1.5));
    }
  }

  save_sram();
  const SnesStats *st = snes_stats();
  fprintf(stderr, "frames %llu, recompiled dispatches %llu, interpreted blocks %llu (ROM %llu)\n",
          (unsigned long long)st->frames, (unsigned long long)st->recomp_dispatches,
          (unsigned long long)st->interp_blocks, (unsigned long long)st->interp_rom_blocks);
  if (st->interp_rom_blocks) {
    char mp[1200];
    path_join(mp, sizeof mp, base_dir, "smw_misses.txt");
    snes_write_misses(mp);
  }
  if (audio) SDL_CloseAudioDevice(audio);
  SDL_DestroyTexture(texture);
  SDL_DestroyRenderer(renderer);
  SDL_DestroyWindow(window);
  SDL_Quit();
  return 0;
}
